--
-- ===========================================================================
--  Northwind (extended)  --  PostgreSQL
-- ===========================================================================
--  Based on: Northwind SQL Database for PostgreSQL, adaption by Alaska Software
--            original sources: http://code.google.com/p/northwindextended/
--
--  This script REPLACES the original one: it drops and recreates the whole
--  Northwind schema, then loads an enlarged, re-dated dataset.
--
--  What changed versus the original file
--  -------------------------------------
--  * All transactional dates live in 2024-01-01 .. 2026-06-30.
--    The original 830 orders were kept and proportionally re-dated into that
--    window (order/required/shipped lags preserved); ~17,882 additional
--    orders were generated on top of them.
--  * Master data enlarged:
--        categories   8  ->  12
--        suppliers   29  ->  75
--        products    77  -> 230
--        customers   91  -> 700
--        employees    9  ->  30
--        shippers     6  ->   9
--        orders     830  -> 18,712
--        order_details 2155 -> 60,463
--  * Two schema changes were necessary / advisable:
--      1) orders.orderid and order_details.orderid are now  integer
--         instead of smallint (a smallint cannot hold the new key range).
--      2) unitprice / discount / freight are now  numeric  instead of  real.
--         With real (float4) a query such as  ROUND(SUM(unitprice*quantity),2)
--         fails in PostgreSQL ("function round(double precision, integer)
--         does not exist") and sums are not exactly reproducible. numeric
--         removes both problems, which matters for the analyst queries below.
--  * One table was dropped: shippers_tmp. It is a byte-for-byte duplicate of
--    shippers (same 6 rows) left behind by the original conversion, it has no
--    foreign keys pointing at it and nothing in Northwind reads it. If some
--    tool of yours does reference it, recreate it with
--        CREATE TABLE shippers_tmp AS SELECT * FROM shippers;
--    Everything else (table names, column names, column order) is unchanged.
--
--  Employee birthdate/hiredate deliberately lie BEFORE the window (people
--  cannot be born in 2024 and still sell in 2024); a handful of employees are
--  hired inside the window and only appear on orders from their hire date on.
--
--  Analytical characteristics that were built into the data on purpose
--  -------------------------------------------------------------------
--  * 2024 and 2025 are complete years, 2026 covers January..June only.
--    -> use 2024 vs 2025 wherever the classic questions used 1996 vs 1997.
--  * Quarterly revenue 2025 vs 2024 grows in Q1/Q2/Q4 but SHRINKS in Q3,
--    so a year-over-year comparison produces both positive and negative
--    growth rates.
--  * Product and customer revenue are heavy-tailed (Pareto), so "top 5"
--    lists are meaningful and a share-of-total calculation is non-trivial.
--  * Customer order frequency and average basket size are independent, so
--    there really are customers with many orders but below-average spend.
--  * Several categories (Produce, Frozen Foods, Beverages, Dairy Products and
--    - only just - Grains/Cereals) decline in H2/2025 versus H1/2025, while
--    Seafood, Confections and Health Foods grow strongly.
--  * Each sales employee has a category affinity, so "top category per
--    employee" differs from employee to employee.
--
--  Load with:   psql -U postgres -d northwind -f northwind_extended_2024_2026.sql
-- ===========================================================================

SET statement_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET client_min_messages = warning;

SET search_path = public, pg_catalog;
SET default_tablespace = '';

BEGIN;

DROP TABLE IF EXISTS customercustomerdemo CASCADE;
DROP TABLE IF EXISTS customerdemographics CASCADE;
DROP TABLE IF EXISTS employeeterritories CASCADE;
DROP TABLE IF EXISTS order_details CASCADE;
DROP TABLE IF EXISTS orders CASCADE;
DROP TABLE IF EXISTS products CASCADE;
DROP TABLE IF EXISTS categories CASCADE;
DROP TABLE IF EXISTS suppliers CASCADE;
DROP TABLE IF EXISTS shippers CASCADE;
DROP TABLE IF EXISTS customers CASCADE;
DROP TABLE IF EXISTS employees CASCADE;
DROP TABLE IF EXISTS territories CASCADE;
DROP TABLE IF EXISTS region CASCADE;
DROP TABLE IF EXISTS usstates CASCADE;

CREATE TABLE categories (
    "categoryid" smallint NOT NULL,
    "categoryname" character varying(15) NOT NULL,
    "description" text,
    "picture" bytea
);

CREATE TABLE customerdemographics (
    "customertypeid" bpchar NOT NULL,
    "customerdesc" text
);

CREATE TABLE customercustomerdemo (
    "customerid" character(5) NOT NULL,
    "customertypeid" bpchar NOT NULL
);

CREATE TABLE customers (
    "customerid" character(5) NOT NULL,
    "companyname" character varying(40) NOT NULL,
    "contactname" character varying(30),
    "contacttitle" character varying(30),
    "address" character varying(60),
    "city" character varying(15),
    "region" character varying(15),
    "postalcode" character varying(10),
    "country" character varying(15),
    "phone" character varying(24),
    "fax" character varying(24)
);

CREATE TABLE employees (
    "employeeid" smallint NOT NULL,
    "lastname" character varying(20) NOT NULL,
    "firstname" character varying(10) NOT NULL,
    "title" character varying(30),
    "titleofcourtesy" character varying(25),
    "birthdate" date,
    "hiredate" date,
    "address" character varying(60),
    "city" character varying(15),
    "region" character varying(15),
    "postalcode" character varying(10),
    "country" character varying(15),
    "homephone" character varying(24),
    "extension" character varying(4),
    "photo" bytea,
    "notes" text,
    "reportsto" smallint,
    "photopath" character varying(255)
);

CREATE TABLE employeeterritories (
    "employeeid" smallint NOT NULL,
    "territoryid" character varying(20) NOT NULL
);

CREATE TABLE order_details (
    "orderid" integer NOT NULL,
    "productid" smallint NOT NULL,
    "unitprice" numeric(10,2) NOT NULL,
    "quantity" smallint NOT NULL,
    "discount" numeric(4,2) NOT NULL
);

CREATE TABLE orders (
    "orderid" integer NOT NULL,
    "customerid" character(5),
    "employeeid" smallint,
    "orderdate" date,
    "requireddate" date,
    "shippeddate" date,
    "shipvia" smallint,
    "freight" numeric(10,2),
    "shipname" character varying(40),
    "shipaddress" character varying(60),
    "shipcity" character varying(15),
    "shipregion" character varying(15),
    "shippostalcode" character varying(10),
    "shipcountry" character varying(15)
);

CREATE TABLE products (
    "productid" smallint NOT NULL,
    "productname" character varying(40) NOT NULL,
    "supplierid" smallint,
    "categoryid" smallint,
    "quantityperunit" character varying(20),
    "unitprice" numeric(10,2),
    "unitsinstock" smallint,
    "unitsonorder" smallint,
    "reorderlevel" smallint,
    "discontinued" integer NOT NULL
);

CREATE TABLE region (
    "regionid" smallint NOT NULL,
    "regiondescription" bpchar NOT NULL
);

CREATE TABLE shippers (
    "shipperid" smallint NOT NULL,
    "companyname" character varying(40) NOT NULL,
    "phone" character varying(24)
);

CREATE TABLE suppliers (
    "supplierid" smallint NOT NULL,
    "companyname" character varying(40) NOT NULL,
    "contactname" character varying(30),
    "contacttitle" character varying(30),
    "address" character varying(60),
    "city" character varying(15),
    "region" character varying(15),
    "postalcode" character varying(10),
    "country" character varying(15),
    "phone" character varying(24),
    "fax" character varying(24),
    "homepage" text
);

CREATE TABLE territories (
    "territoryid" character varying(20) NOT NULL,
    "territorydescription" bpchar NOT NULL,
    "regionid" smallint NOT NULL
);

CREATE TABLE usstates (
    "stateid" smallint NOT NULL,
    "statename" character varying(100),
    "stateabbr" character varying(2),
    "stateregion" character varying(50)
);


-- ============================ categories

-- ============================ region / territories / usstates

-- ============================ shippers

-- ============================ suppliers (29 original + 46 new)

-- ============================ employees (9 original + 21 new)

-- ============================ employeeterritories

-- ============================ customers (91 original + 359 new)

-- ============================ customer demographics / segments

-- ============================ products (77 original + 153 new)

-- ============================ orders (18712)

-- ============================ order_details (60463)

-- ---------------------------------------------------------------- keys
ALTER TABLE ONLY categories           ADD CONSTRAINT pk_categories PRIMARY KEY ("categoryid");
ALTER TABLE ONLY customerdemographics ADD CONSTRAINT pk_customerdemographics PRIMARY KEY ("customertypeid");
ALTER TABLE ONLY customers            ADD CONSTRAINT pk_customers PRIMARY KEY ("customerid");
ALTER TABLE ONLY customercustomerdemo ADD CONSTRAINT pk_customercustomerdemo PRIMARY KEY ("customerid", "customertypeid");
ALTER TABLE ONLY employees            ADD CONSTRAINT pk_employees PRIMARY KEY ("employeeid");
ALTER TABLE ONLY employeeterritories  ADD CONSTRAINT pk_employeeterritories PRIMARY KEY ("employeeid", "territoryid");
ALTER TABLE ONLY order_details        ADD CONSTRAINT pk_order_details PRIMARY KEY ("orderid", "productid");
ALTER TABLE ONLY orders               ADD CONSTRAINT pk_orders PRIMARY KEY ("orderid");
ALTER TABLE ONLY products             ADD CONSTRAINT pk_products PRIMARY KEY ("productid");
ALTER TABLE ONLY region               ADD CONSTRAINT pk_region PRIMARY KEY ("regionid");
ALTER TABLE ONLY shippers             ADD CONSTRAINT pk_shippers PRIMARY KEY ("shipperid");
ALTER TABLE ONLY suppliers            ADD CONSTRAINT pk_suppliers PRIMARY KEY ("supplierid");
ALTER TABLE ONLY territories          ADD CONSTRAINT pk_territories PRIMARY KEY ("territoryid");
ALTER TABLE ONLY usstates             ADD CONSTRAINT pk_usstates PRIMARY KEY ("stateid");

-- ---------------------------------------------------- referential integrity
ALTER TABLE ONLY products   ADD CONSTRAINT fk_products_categories  FOREIGN KEY ("categoryid") REFERENCES categories("categoryid");
ALTER TABLE ONLY products   ADD CONSTRAINT fk_products_suppliers   FOREIGN KEY ("supplierid") REFERENCES suppliers("supplierid");
ALTER TABLE ONLY orders     ADD CONSTRAINT fk_orders_customers     FOREIGN KEY ("customerid") REFERENCES customers("customerid");
ALTER TABLE ONLY orders     ADD CONSTRAINT fk_orders_employees     FOREIGN KEY ("employeeid") REFERENCES employees("employeeid");
ALTER TABLE ONLY orders     ADD CONSTRAINT fk_orders_shippers      FOREIGN KEY ("shipvia")    REFERENCES shippers("shipperid");
ALTER TABLE ONLY order_details ADD CONSTRAINT fk_od_orders         FOREIGN KEY ("orderid")    REFERENCES orders("orderid");
ALTER TABLE ONLY order_details ADD CONSTRAINT fk_od_products       FOREIGN KEY ("productid")  REFERENCES products("productid");
ALTER TABLE ONLY employees  ADD CONSTRAINT fk_employees_reportsto  FOREIGN KEY ("reportsto")  REFERENCES employees("employeeid");
ALTER TABLE ONLY territories ADD CONSTRAINT fk_territories_region  FOREIGN KEY ("regionid")   REFERENCES region("regionid");
ALTER TABLE ONLY employeeterritories ADD CONSTRAINT fk_et_employees   FOREIGN KEY ("employeeid")  REFERENCES employees("employeeid");
ALTER TABLE ONLY employeeterritories ADD CONSTRAINT fk_et_territories FOREIGN KEY ("territoryid") REFERENCES territories("territoryid");
ALTER TABLE ONLY customercustomerdemo ADD CONSTRAINT fk_ccd_customers FOREIGN KEY ("customerid") REFERENCES customers("customerid");
ALTER TABLE ONLY customercustomerdemo ADD CONSTRAINT fk_ccd_demo      FOREIGN KEY ("customertypeid") REFERENCES customerdemographics("customertypeid");

-- ---------------------------------------------------------------- indexes
CREATE INDEX idx_orders_orderdate   ON orders ("orderdate");
CREATE INDEX idx_orders_customerid  ON orders ("customerid");
CREATE INDEX idx_orders_employeeid  ON orders ("employeeid");
CREATE INDEX idx_od_productid       ON order_details ("productid");
CREATE INDEX idx_products_category  ON products ("categoryid");

COMMIT;

ANALYZE;
